export function graphRagSynthesis(agentOutputs) {
  const graph = {};
  agentOutputs.forEach(output => {
    const { entity, relationships, confidence } = output;
    if (!graph[entity]) graph[entity] = { relationships: {}, confidence: 0 };
    graph[entity].confidence = Math.max(graph[entity].confidence, confidence);
    relationships.forEach(rel => {
      if (!graph[entity].relationships[rel.target]) {
        graph[entity].relationships[rel.target] = { weight: 0 };
      }
      graph[entity].relationships[rel.target].weight += rel.weight;
    });
  });
  return graph;
}

export function resolveConflicts(graph) {
  Object.keys(graph).forEach(entity => {
    const relationships = graph[entity].relationships;
    Object.keys(relationships).forEach(target => {
      if (relationships[target].weight < 0.5) {
        delete relationships[target];
      }
    });
  });
  return graph;
}